"use client";

import * as React from "react";
import {
  ListFilter,
  X,
  Search,
  Type,
  Hash,
  Calendar,
  ToggleLeft,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { FilterRow } from "./filter-row";
import { FilterValueSelector } from "./filter-value-selector";
import { FilterOperatorSelector } from "./filter-operator-selector";
import { FilterDateValue } from "./filter-date-value";
import { FilterBooleanValue } from "./filter-boolean-value";
import {
  type QueryFilter,
  type FilterValue,
  type FilterType,
  getDefaultOperator,
  defineDefaultFilterValue,
  operatorSupportsMultipleValues,
  operatorRequiresValue,
} from "../../lib/filter-utils";
import {
  type FieldPath,
  type Filter,
  type FilterValueFor,
  type OperatorsForType,
  isValidOperatorForType,
} from "@woltz/rich-domain";
import type { UseCriteriaReturn } from "@/types/use-criteria.type";
import { cn } from "@/lib/utils";

interface FilterProps {
  fields: QueryFilter[];
  filters: Filter<string, unknown>[];
  addOrReplaceByIndex: UseCriteriaReturn<unknown>["addOrReplaceByIndex"];
  removeFilter: (index: number) => void;
  clearFilters: () => void;
}

const TYPE_ICONS: Record<FilterType, React.ReactNode> = {
  string: <Type className="h-4 w-4" />,
  number: <Hash className="h-4 w-4" />,
  date: <Calendar className="h-4 w-4" />,
  boolean: <ToggleLeft className="h-4 w-4" />,
};

export function Filter({
  fields,
  filters,
  addOrReplaceByIndex,
  removeFilter,
  clearFilters,
}: FilterProps) {
  const [addFilterStep, setAddFilterStep] = React.useState<
    null | "field" | "value"
  >(null);
  const [search, setSearch] = React.useState("");
  const [selectedFieldForAdd, setSelectedFieldForAdd] =
    React.useState<QueryFilter | null>(null);
  const [tempOperator, setTempOperator] =
    React.useState<FilterValue["operator"]>("equals");
  const [tempValue, setTempValue] = React.useState<FilterValue["value"]>(null);

  const filterValues: FilterValue[] = filters.map((filter) => ({
    field: filter.field,
    operator: filter.operator as FilterValue["operator"],
    value: filter.value as FilterValue["value"],
  }));

  const usedFields = filters.map((filter) => filter.field);
  const remainingFields = fields.filter(
    (field) => !usedFields.includes(field.field)
  );

  const HAS_FIELDS_REMAINING = remainingFields.length > 0;

  const filteredRemainingFields = remainingFields.filter((field) =>
    field.fieldLabel.toLowerCase().includes(search.toLowerCase())
  );

  const handleSelectFieldForAdd = (field: QueryFilter) => {
    setSelectedFieldForAdd(field);
    const defaultOp = getDefaultOperator(field.type);
    setTempOperator(defaultOp);
    setTempValue(defineDefaultFilterValue(field.type, defaultOp));
    setSearch("");
    setAddFilterStep("value");
  };

  const handleConfirmAddFilter = () => {
    if (!selectedFieldForAdd) return;

    addOrReplaceByIndex({
      field: selectedFieldForAdd.field as FieldPath<unknown>,
      operator: tempOperator as OperatorsForType<never>,
      value: tempValue as FilterValueFor<never>,
    });

    setAddFilterStep(null);
    setSelectedFieldForAdd(null);
    setTempOperator("equals");
    setTempValue(null);
  };

  const handleCancelAddFilter = () => {
    setAddFilterStep(null);
    setSelectedFieldForAdd(null);
    setTempOperator("equals");
    setTempValue(null);
    setSearch("");
  };

  const handleUpdateFilter = (index: number, newValue: FilterValue) => {
    const prevFilter = filterValues[index];
    if (!prevFilter) return;

    const newField = fields.find((f) => f.field === newValue.field);
    const prevField = fields.find((f) => f.field === prevFilter.field);
    if (!newField || !prevField) return;

    const fieldTypeChanged = prevField.type !== newField.type;

    const operator = fieldTypeChanged
      ? getDefaultOperator(newField.type)
      : newValue.operator;

    let value =
      newValue.value === null || fieldTypeChanged
        ? defineDefaultFilterValue(newField.type, newValue.operator)
        : newValue.value;

    const newOperatorIsArrayOperator = operatorSupportsMultipleValues(operator);
    const prevOperatorIsArrayOperator = operatorSupportsMultipleValues(
      prevFilter.operator
    );

    if (prevOperatorIsArrayOperator && !newOperatorIsArrayOperator) {
      value = null;
    }

    addOrReplaceByIndex({
      field: newField.field as FieldPath<unknown>,
      operator: operator as OperatorsForType<never>,
      value: value as FilterValueFor<never>,
      replaceIndex: index,
    });
  };

  const handleSelectField = (index: number, newValue: FilterValue) => {
    const filterToUpdate = filters[index];
    if (!filterToUpdate) return;

    const newField = fields.find((f) => f.field === newValue.field);
    const oldField = fields.find((f) => f.field === filterToUpdate.field);

    if (!newField || !oldField) return;

    let value = filterToUpdate.value;
    let operator = newValue.operator;

    if (newField.type !== oldField.type) {
      operator = getDefaultOperator(newField.type);
      value = defineDefaultFilterValue(newField.type);
    }

    addOrReplaceByIndex({
      field: newValue.field as FieldPath<unknown>,
      operator: operator as OperatorsForType<never>,
      value: value as FilterValueFor<never>,
      replaceIndex: index,
    });
  };

  const handleRemoveFilter = (index: number) => {
    removeFilter(index);
  };

  const canAddFilter = React.useMemo(() => {
    if (!selectedFieldForAdd) return false;
    return isValidOperatorForType(tempValue, tempOperator);
  }, [tempValue, tempOperator, selectedFieldForAdd]);

  return (
    <div className="flex flex-wrap items-center gap-2">
      {filterValues.map((filter, index) => (
        <FilterRow
          key={`${filter.field}-${index}`}
          fields={fields}
          value={filter}
          onChange={(newValue) => handleUpdateFilter(index, newValue)}
          onSelectField={(newValue) => handleSelectField(index, newValue)}
          onRemove={() => handleRemoveFilter(index)}
          usedFields={usedFields}
        />
      ))}
      <div className="flex items-center gap-2">
        {filterValues.length > 0 && (
          <Button
            variant="outline"
            size="sm"
            className="h-8 gap-1.5 bg-transparent"
            onClick={clearFilters}
          >
            <X className="h-4 w-4" />
          </Button>
        )}
        <Popover
          open={addFilterStep !== null}
          onOpenChange={(open) => !open && handleCancelAddFilter()}
        >
          <PopoverTrigger asChild>
            <Button
              variant="outline"
              size="sm"
              className="h-8 gap-1.5 bg-transparent"
              disabled={!HAS_FIELDS_REMAINING}
              onClick={() => setAddFilterStep("field")}
            >
              {filterValues.length === 0 ? (
                <>
                  <ListFilter className="h-4 w-4" />
                  Add Filter
                </>
              ) : (
                <ListFilter className="h-4 w-4" />
              )}
            </Button>
          </PopoverTrigger>
          <PopoverContent
            className={cn(
              addFilterStep === "field" ? "w-52 p-0" : "min-w-64 p-3",
              "bg-card"
            )}
            align="start"
          >
            {addFilterStep === "field" ? (
              <>
                <div className="p-2 border-b border-border">
                  <div className="relative">
                    <Search className="absolute left-2 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                      placeholder="Search fields..."
                      value={search}
                      onChange={(e) => setSearch(e.target.value)}
                      className="h-8 pl-8"
                    />
                  </div>
                </div>
                <div className="max-h-60 overflow-y-auto p-1">
                  {filteredRemainingFields.map((field) => (
                    <button
                      key={field.field}
                      onClick={() => handleSelectFieldForAdd(field)}
                      className="flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm hover:bg-accent"
                    >
                      <span className="text-muted-foreground">
                        {TYPE_ICONS[field.type]}
                      </span>
                      <span className="flex-1 text-left">
                        {field.fieldLabel}
                      </span>
                    </button>
                  ))}
                  {filteredRemainingFields.length === 0 && (
                    <div className="py-6 text-center text-sm text-muted-foreground">
                      {search
                        ? "No fields found"
                        : "All fields are already in use"}
                    </div>
                  )}
                </div>
              </>
            ) : addFilterStep === "value" && selectedFieldForAdd ? (
              <div className="space-y-3">
                <div className="flex items-center gap-2 pb-2 border-b">
                  <span className="text-muted-foreground">
                    {TYPE_ICONS[selectedFieldForAdd.type]}
                  </span>
                  <span className="font-medium text-foreground text-sm">
                    {selectedFieldForAdd.fieldLabel}
                  </span>
                </div>

                <div className="flex items-center gap-2 ">
                  <div className="space-y-2 h-7">
                    <FilterOperatorSelector
                      type={selectedFieldForAdd.type}
                      selectedOperator={tempOperator}
                      onSelect={(op) => {
                        setTempOperator(op);
                        if (!operatorRequiresValue(op)) {
                          setTempValue(null);
                        }
                      }}
                    />
                  </div>

                  {operatorRequiresValue(tempOperator) && (
                    <div className="space-y-2 flex-1 h-7">
                      {selectedFieldForAdd.type === "date" ? (
                        <FilterDateValue
                          operator={tempOperator}
                          value={tempValue as string | [string, string] | null}
                          onChange={setTempValue}
                        />
                      ) : selectedFieldForAdd.type === "boolean" ? (
                        <FilterBooleanValue
                          value={tempValue as boolean | null}
                          onChange={setTempValue}
                        />
                      ) : (
                        <FilterValueSelector
                          filter={selectedFieldForAdd}
                          operator={tempOperator}
                          value={tempValue as string | string[]}
                          onChange={setTempValue}
                        />
                      )}
                    </div>
                  )}
                </div>

                <div className="flex gap-2 pt-2">
                  <Button
                    variant="outline"
                    size="sm"
                    className="h-7 flex-1 text-xs"
                    onClick={handleCancelAddFilter}
                  >
                    Cancel
                  </Button>
                  <Button
                    size="sm"
                    className="h-7 flex-1 text-xs"
                    disabled={!canAddFilter}
                    onClick={handleConfirmAddFilter}
                  >
                    Add Filter
                  </Button>
                </div>
              </div>
            ) : null}
          </PopoverContent>
        </Popover>
      </div>
    </div>
  );
}

"use client";
import { X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { FilterFieldSelector } from "./filter-field-selector";
import { FilterOperatorSelector } from "./filter-operator-selector";
import { FilterValueSelector } from "./filter-value-selector";
import { FilterDateValue } from "./filter-date-value";
import { FilterBooleanValue } from "./filter-boolean-value";
import {
  type QueryFilter,
  type FilterValue,
  type FilterOperator,
  getDefaultOperator,
  operatorRequiresValue,
} from "@/lib/filter-utils";

interface FilterRowProps {
  fields: QueryFilter[];
  value: FilterValue;
  onSelectField: (value: FilterValue) => void;
  onChange: (value: FilterValue) => void;
  onRemove: () => void;
  usedFields?: string[];
}

export function FilterRow({
  fields,
  value,
  onChange,
  onRemove,
  onSelectField,
  usedFields = [],
}: FilterRowProps) {
  const currentField = fields.find((f) => f.field === value.field);
  const type = currentField?.type || "string";

  const handleFieldChange = (field: QueryFilter) => {
    onSelectField({
      field: field.field,
      operator: getDefaultOperator(field.type),
      value: null,
    });
  };

  const handleOperatorChange = (operator: FilterOperator) => {
    onChange({
      ...value,
      operator,
      value: operatorRequiresValue(operator) ? value.value : null,
    });
  };

  const handleValueChange = (newValue: FilterValue["value"]) => {
    onChange({
      ...value,
      value: newValue,
    });
  };

  const renderValueInput = () => {
    if (!operatorRequiresValue(value.operator)) {
      return null;
    }

    if (type === "date") {
      return (
        <FilterDateValue
          operator={value.operator}
          value={value.value as string | [string, string] | null}
          onChange={handleValueChange}
        />
      );
    }

    if (type === "boolean") {
      return (
        <FilterBooleanValue
          value={value.value as boolean | null}
          onChange={handleValueChange}
        />
      );
    }

    if (currentField) {
      return (
        <FilterValueSelector
          filter={currentField}
          operator={value.operator}
          value={value.value as string | string[]}
          onChange={handleValueChange}
        />
      );
    }

    return null;
  };

  return (
    <div className="group flex items-center gap-1.5 rounded-md border border-border bg-card p-1">
      <FilterFieldSelector
        fields={fields}
        selectedField={value.field}
        onSelect={handleFieldChange}
        usedFields={usedFields}
      />
      <FilterOperatorSelector
        type={type}
        selectedOperator={value.operator}
        onSelect={handleOperatorChange}
      />
      {renderValueInput()}
      <Button
        variant="ghost"
        size="sm"
        className="h-7 w-7 p-0 text-muted-foreground hover:text-foreground"
        onClick={onRemove}
      >
        <X className="h-4 w-4" />
      </Button>
    </div>
  );
}

"use client";

import * as React from "react";
import { Check, Search, X, Plus, CircleDashed } from "lucide-react";
import { Popover, PopoverContent, PopoverTrigger } from "../ui/popover";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import type { QueryFilter, FilterOperator } from "../../lib/filter-utils";
import { operatorSupportsMultipleValues } from "../../lib/filter-utils";

interface FilterValueSelectorProps {
  filter: QueryFilter;
  operator: FilterOperator;
  value: string | string[];
  onChange: (value: string | string[]) => void;
}

export function FilterValueSelector({
  filter,
  operator,
  value,
  onChange,
}: FilterValueSelectorProps) {
  const [open, setOpen] = React.useState(false);
  const [search, setSearch] = React.useState("");
  const isMultiple = operatorSupportsMultipleValues(operator);
  const hasOptions = filter.options && filter.options.length > 0;

  const selectedValues = Array.isArray(value) ? value : value ? [value] : [];

  const filteredOptions =
    filter.options?.filter((opt) =>
      opt.label.toLowerCase().includes(search.toLowerCase())
    ) || [];

  const handleSelect = (optionValue: string) => {
    if (isMultiple) {
      const newValues = selectedValues.includes(optionValue)
        ? selectedValues.filter((v) => v !== optionValue)
        : [...selectedValues, optionValue];
      onChange(newValues);
    } else {
      onChange(optionValue);
      setOpen(false);
    }
  };

  const handleRemoveValue = (optionValue: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (isMultiple) {
      onChange(selectedValues.filter((v) => v !== optionValue));
    } else {
      onChange("");
    }
  };

  const getOptionLabel = (val: string) => {
    return filter.options?.find((opt) => opt.value === val)?.label || val;
  };

  const getOptionIcon = (val: string) => {
    return (
      filter.options?.find((opt) => opt.value === val)?.icon ?? <CircleDashed />
    );
  };

  if (hasOptions) {
    const renderDisplayContent = () => {
      if (selectedValues.length === 0) {
        return (
          <div className="flex items-center gap-1 text-muted-foreground">
            <Plus className="h-3.5 w-3.5" />
            <span className="text-xs">Selecionar</span>
          </div>
        );
      }

      if (selectedValues.length === 1) {
        const val = selectedValues[0];
        return (
          <div className="flex items-center gap-1">
            {getOptionIcon(val)}
            <span className="text-xs">{getOptionLabel(val)}</span>
            <div
              onClick={(e) => handleRemoveValue(val, e)}
              role="button"
              className="ml-0.5 rounded-full hover:bg-muted-foreground/20"
            >
              <X className="h-3 w-3" />
            </div>
          </div>
        );
      }

      return (
        <div className="flex items-center gap-1.5">
          <div className="flex items-center -space-x-2.5">
            {selectedValues.slice(0, 3).map((val) => {
              const icon = getOptionIcon(val);
              return icon ? (
                <div
                  key={val}
                  className="rounded-full border bg-background p-0.5"
                >
                  <span className="text-[10px]">{icon}</span>
                </div>
              ) : null;
            })}
          </div>
          <span className="text-xs font-medium truncate">
            {selectedValues.length} selected
            {selectedValues.length > 1 ? "s" : ""}
          </span>
        </div>
      );
    };

    return (
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <Button
            variant="secondary"
            size="sm"
            className="h-7 gap-1 pl-1.5 pr-1.5 text-xs font-normal hover:bg-secondary/80"
          >
            {renderDisplayContent()}
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-52 p-0" align="start">
          <div className="p-2 border-b border-border">
            <div className="relative">
              <Search className="absolute left-2 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                placeholder="Search options..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="h-8 pl-8"
              />
            </div>
          </div>
          <div className="max-h-60 overflow-y-auto p-1">
            {filteredOptions.map((option) => (
              <button
                key={option.value}
                onClick={() => handleSelect(option.value)}
                className={cn(
                  "flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm hover:bg-accent",
                  selectedValues.includes(option.value) && "bg-accent"
                )}
              >
                {option.icon && (
                  <span className="text-muted-foreground">{option.icon}</span>
                )}
                <span className="flex-1 text-left">{option.label}</span>
                {selectedValues.includes(option.value) && (
                  <Check className="h-4 w-4" />
                )}
              </button>
            ))}
            {filteredOptions.length === 0 && (
              <div className="py-6 text-center text-sm text-muted-foreground">
                No options found
              </div>
            )}
          </div>
        </PopoverContent>
      </Popover>
    );
  }

  return (
    <Input
      type={filter.type === "number" ? "number" : "text"}
      placeholder="Enter value..."
      value={typeof value === "string" ? value : ""}
      onChange={(e) => onChange(e.target.value)}
      className="h-7 w-32 text-sm"
    />
  );
}

"use client";

import * as React from "react";
import { Check, ChevronDown } from "lucide-react";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import {
  type FilterType,
  type FilterOperator,
  getOperatorsByType,
  OPERATOR_LABELS,
} from "@/lib/filter-utils";

interface FilterOperatorSelectorProps {
  type: FilterType;
  selectedOperator: FilterOperator;
  onSelect: (operator: FilterOperator) => void;
}

export function FilterOperatorSelector({
  type,
  selectedOperator,
  onSelect,
}: FilterOperatorSelectorProps) {
  const [open, setOpen] = React.useState(false);
  const operators = getOperatorsByType(type);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="secondary"
          size="sm"
          className="h-7 gap-1 px-2 text-xs font-normal"
        >
          {OPERATOR_LABELS[selectedOperator]}
          <ChevronDown className="h-3 w-3 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-44 p-1" align="start">
        <div className="max-h-60 overflow-y-auto">
          {operators.map((operator) => (
            <button
              key={operator}
              onClick={() => {
                onSelect(operator);
                setOpen(false);
              }}
              className={cn(
                "flex w-full items-center justify-between rounded-sm px-2 py-1.5 text-sm hover:bg-accent",
                selectedOperator === operator && "bg-accent"
              )}
            >
              <span>{OPERATOR_LABELS[operator]}</span>
              {selectedOperator === operator && <Check className="h-4 w-4" />}
            </button>
          ))}
        </div>
      </PopoverContent>
    </Popover>
  );
}

"use client";

import * as React from "react";
import { format } from "date-fns";
import { CalendarIcon } from "lucide-react";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import { cn } from "@/lib/utils";
import type { FilterOperator } from "@/lib/filter-utils";

interface FilterDateValueProps {
  operator: FilterOperator;
  value: string | [string, string] | null;
  onChange: (value: string | [string, string] | null) => void;
}

export function FilterDateValue({
  operator,
  value,
  onChange,
}: FilterDateValueProps) {
  const [open, setOpen] = React.useState(false);
  const isBetween = operator === "between";

  const dateRange = isBetween && Array.isArray(value) ? value : undefined;
  const singleDate =
    !isBetween && value ? new Date(value as string) : undefined;

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="secondary"
          size="sm"
          className={cn(
            "h-7 justify-start gap-1.5 px-2 text-xs font-normal",
            !value && "text-muted-foreground"
          )}
        >
          <CalendarIcon className="h-3.5 w-3.5" />
          {singleDate
            ? format(singleDate, "MMM d, yyyy")
            : dateRange
            ? `${format(new Date(dateRange[0]), "MMM d")} - ${format(
                new Date(dateRange[1]),
                "MMM d"
              )}`
            : "Pick a date"}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-auto p-0" align="start">
        {isBetween ? (
          <Calendar
            mode="range"
            selected={
              dateRange
                ? { from: new Date(dateRange[0]), to: new Date(dateRange[1]) }
                : undefined
            }
            onSelect={(range) => {
              if (range?.from && range?.to) {
                onChange([range.from.toISOString(), range.to.toISOString()]);
                setOpen(false);
              }
            }}
            autoFocus
            numberOfMonths={2}
          />
        ) : (
          <Calendar
            mode="single"
            selected={singleDate}
            onSelect={(date) => {
              onChange(date?.toISOString() || null);
              setOpen(false);
            }}
            autoFocus
          />
        )}
      </PopoverContent>
    </Popover>
  );
}

"use client"

import * as React from "react"
import { Check, ChevronDown } from "lucide-react"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

interface FilterBooleanValueProps {
  value: boolean | null
  onChange: (value: boolean) => void
}

const OPTIONS = [
  { label: "True", value: true },
  { label: "False", value: false },
]

export function FilterBooleanValue({ value, onChange }: FilterBooleanValueProps) {
  const [open, setOpen] = React.useState(false)

  const selectedLabel = value === null ? "Select..." : value ? "True" : "False"

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="secondary"
          size="sm"
          className={cn("h-7 gap-1 px-2 text-xs font-normal", value === null && "text-muted-foreground")}
        >
          {selectedLabel}
          <ChevronDown className="h-3 w-3 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-28 p-1" align="start">
        {OPTIONS.map((option) => (
          <button
            key={option.label}
            onClick={() => {
              onChange(option.value)
              setOpen(false)
            }}
            className={cn(
              "flex w-full items-center justify-between rounded-sm px-2 py-1.5 text-sm hover:bg-accent",
              value === option.value && "bg-accent",
            )}
          >
            <span>{option.label}</span>
            {value === option.value && <Check className="h-4 w-4" />}
          </button>
        ))}
      </PopoverContent>
    </Popover>
  )
}

import type {
  BooleanOperators,
  DateOperators,
  NumberOperators,
  StringOperators,
} from "@woltz/rich-domain";
import type React from "react";

export type FilterType = "string" | "number" | "boolean" | "date";

export type FilterOperator =
  | StringOperators
  | NumberOperators
  | DateOperators
  | BooleanOperators;

export type QueryFilter = {
  type: FilterType;
  field: string;
  fieldLabel: string;
  multiSelect?: boolean;
  options?: {
    label: string;
    value: string;
    icon?: React.ReactNode;
  }[];
};

export type FilterValue = {
  field: string;
  operator: FilterOperator;
  value:
    | string
    | string[]
    | number
    | number[]
    | boolean
    | Date
    | [Date, Date]
    | null;
};

export type OperatorLabels = Record<FilterOperator, string>;
export const OPERATOR_LABELS: OperatorLabels = {
  equals: "is",
  notEquals: "is not",
  contains: "contains",
  startsWith: "starts with",
  endsWith: "ends with",
  in: "has any of",
  notIn: "has none of",
  greaterThan: "greater than",
  greaterThanOrEqual: "greater or equal",
  lessThan: "less than",
  lessThanOrEqual: "less or equal",
  between: "between",
  isNull: "is empty",
  isNotNull: "is not empty",
};

export function defineDefaultFilterValue(
  type: FilterType,
  operator?: FilterOperator
) {
  if (operator === "isNull" || operator === "isNotNull") {
    return null;
  }

  let defaultValue: FilterValue["value"];
  switch (type) {
    case "string": {
      defaultValue = "";
      break;
    }
    case "number": {
      defaultValue = 0;
      break;
    }
    case "date": {
      defaultValue = null;
      break;
    }
    case "boolean": {
      defaultValue = false;
      break;
    }
    default: {
      defaultValue = null;
      break;
    }
  }
  return defaultValue;
}

export const STRING_OPERATORS: StringOperators[] = [
  "equals",
  "notEquals",
  "contains",
  "startsWith",
  "endsWith",
  "in",
  "notIn",
  "isNull",
  "isNotNull",
];

export const NUMBER_OPERATORS: NumberOperators[] = [
  "equals",
  "notEquals",
  "greaterThan",
  "greaterThanOrEqual",
  "lessThan",
  "lessThanOrEqual",
  "in",
  "notIn",
  "between",
  "isNull",
  "isNotNull",
];

export const DATE_OPERATORS: DateOperators[] = [
  "equals",
  "notEquals",
  "greaterThan",
  "greaterThanOrEqual",
  "lessThan",
  "lessThanOrEqual",
  "in",
  "notIn",
  "between",
  "isNull",
  "isNotNull",
];

export const BOOLEAN_OPERATORS: BooleanOperators[] = [
  "equals",
  "notEquals",
  "isNull",
  "isNotNull",
];

export function getOperatorsByType(type: FilterType): FilterOperator[] {
  switch (type) {
    case "string":
      return STRING_OPERATORS;
    case "number":
      return NUMBER_OPERATORS;
    case "date":
      return DATE_OPERATORS;
    case "boolean":
      return BOOLEAN_OPERATORS;
  }
}

export function getDefaultOperator(type: FilterType): FilterOperator {
  switch (type) {
    case "string":
      return "contains";
    case "number":
      return "equals";
    case "date":
      return "equals";
    case "boolean":
      return "equals";
  }
}

export function operatorRequiresValue(operator: FilterOperator): boolean {
  return operator !== "isNull" && operator !== "isNotNull";
}

export function operatorSupportsMultipleValues(
  operator: FilterOperator
): boolean {
  return operator === "in" || operator === "notIn";
}
